#include <SDL3/SDL.h>
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
static void click(SDL_Renderer*r,float x,float y){float wx,wy;SDL_RenderCoordinatesToWindow(r,x,y,&wx,&wy);SDL_Window*w=SDL_GetRenderWindow(r);SDL_Event e={0};e.type=SDL_EVENT_MOUSE_MOTION;e.motion.windowID=SDL_GetWindowID(w);e.motion.x=wx;e.motion.y=wy;SDL_PushEvent(&e);e.type=SDL_EVENT_MOUSE_BUTTON_DOWN;e.button.windowID=SDL_GetWindowID(w);e.button.button=SDL_BUTTON_LEFT;e.button.x=wx;e.button.y=wy;e.button.down=true;SDL_PushEvent(&e);e.type=SDL_EVENT_MOUSE_BUTTON_UP;e.button.down=false;SDL_PushEvent(&e);}
static void shot(SDL_Renderer*r,const char*name){const char*d=getenv("CITY_SMOKE_SCREEN_DIR");if(!d)return;char p[1024];snprintf(p,sizeof(p),"%s/%s.bmp",d,name);SDL_Surface*s=SDL_RenderReadPixels(r,NULL);if(s){SDL_SaveBMP(s,p);SDL_DestroySurface(s);fprintf(stderr,"[smoke] captured %s\n",name);}}
static SDL_Renderer* render;static Uint64 begin;static int phase,captured=-1;
bool SDL_RenderPresent(SDL_Renderer*r){static bool(*real)(SDL_Renderer*);if(!real)real=dlsym(RTLD_NEXT,"SDL_RenderPresent");render=r;if(!begin)begin=SDL_GetTicks();if(captured!=phase){shot(r,phase==0?"wayland-main":phase==1?"wayland-settings":"wayland-volume");captured=phase;}return real(r);}
bool SDL_WaitEventTimeout(SDL_Event*e,Sint32 timeout){static bool(*real)(SDL_Event*,Sint32);if(!real)real=dlsym(RTLD_NEXT,"SDL_WaitEventTimeout");if(render){Uint64 t=SDL_GetTicks()-begin;int w,h;SDL_RendererLogicalPresentation mode;SDL_GetRenderLogicalPresentation(render,&w,&h,&mode);if(phase==0&&t>500){phase=1;click(render,204,h*.5f+68);fprintf(stderr,"[smoke] settings click\n");}else if(phase==1&&t>1100){phase=2;for(int i=0;i<30;i++){click(render,w*.924242f,h*.25f);click(render,w*.924242f,h*.45f);}fprintf(stderr,"[smoke] 30 music and effects plus clicks\n");}else if(phase==2&&t>1800){phase=3;SDL_Event quit={0};quit.type=SDL_EVENT_QUIT;SDL_PushEvent(&quit);fprintf(stderr,"[smoke] quit event\n");}}return real(e,timeout>50?50:timeout);}
